// EN translation FIRST PASS. Literary editorial approval outstanding.
const OUTCOMES_EN_E431_E500 = Object.freeze({"E431.1":{"s":"An old golden cache opens behind the wall, and Thorne nervously checks the remaining three meters. The miners take the find before new drilling.","f":"As soon as the drill passes the warned depth, armed creatures emerge from the passage. The battle begins."},"E431.2":{"s":"You support the miners, and Thorne seals the dangerous mine until the origin of the letter is determined. Workers put away tools."},"E431.3":{"s":"{{heroName}} braces the tunnel wall and finds a cache of gold and provisions beside the crack. The miners thank you for making the inspection safe.","f":"The support breaks down, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The mine face settles dangerously, but none of the eligible fighters is gravely wounded. The inspection is called off."}},"E431.4":{"s":"You leave the mine with the first shift. Thorne once again reads the letter, dated today."},"E432.1":{"s":"Belm agrees to remove the name block and keep it in the family room. Repairers pay in gold for the saved arch.","f":"Belm demands that the signature be left in the same place and prohibits work. The crack continues to widen."},"E432.2":{"s":"You leave supplies for the workers to build temporary supports. The foreman rewards the urgent help with gold."},"E432.3":{"s":"{{heroName}} removes the entire inscribed block and installs a fresh support. Belm rewards you with gold for preserving Gorak's name.","f":"The damaged arch sags and seriously injures {{affectedHeroName}}.","v":{"nf":"The arch sags dangerously, but none of the eligible fighters are gravely wounded. The transfer of the signature has to be postponed."}},"E432.4":{"s":"You leave, leaving Belm to guard the ancestor's signature. Sand pours out of the crack above him again."},"E433.1":{"s":"You shut down both furnaces while the workers divert water away from the shafts. The smiths reward you with supplies for averting disaster.","f":"Garn and Mora declare the interference a violation of the competition and lead their supporters into a confrontation."},"E433.2":{"s":"You buy back coal and camp supplies before the students throw everything into the forges. A stream is already flowing in the square."},"E433.3":{"s":"{{heroName}} digs a diversion channel that keeps water out of the lower shafts. The miners reward you with gold for saving their workings.","f":"Under the pressure of water, the fastening breaks off, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The flow damages temporary defenses, but no eligible combatants are gravely wounded. The adits remain under threat."}},"E433.4":{"s":"You go to the heights while Garn and Mora argue over whose forge melted the area first. The alarm bells are getting louder."},"E434.1":{"s":"The new path leads to the food supply left behind, and the statue's finger points there. Keeper Dul hesitates to call this a coincidence.","f":"Around the bend in the foggy path, armed raiders emerge. A skirmish begins."},"E434.2":{"s":"You choose a proven road and spend extra supplies on a long journey. The statue remains pointing into the fog."},"E434.3":{"s":"{{heroName}} finds a safe descent and a cache of supplies on the new trail. The caravaners thank you for the reconnaissance.","f":"On an unfamiliar slope, {{affectedHeroName}} is gravely wounded by a landslide.","v":{"nf":"A collapse stops exploration, but none of the eligible fighters are gravely wounded. The new path remains untested."}},"E434.4":{"s":"You let the first caravan make the choice for itself. Dul is still looking at the finger of the ancient guide."},"E435.1":{"s":"You pay a toll calculated by the curious comparison of your cloak with a beard. The official lets your party pass with visible relief."},"E435.2":{"s":"You point out that the law does not define a beard as a mandatory requirement for travel. The official returns the gold for the wrong tariff.","f":"The official considers a ponytail to be an acceptable measure and collects gold for objection."},"E435.3":{"s":"{{heroName}} finds in the old rules the exemption of travelers without a beard from the fee. The treasury receives the returned gold.","f":"{{heroName}} does not find an exception, and you have to pay for the archive check. The treasury is losing gold."},"E435.4":{"s":"You waste supplies on the outer road and leave an official to measure the length of someone else's cloak."},"E436.1":{"s":"You pull a worker from beneath the rubble, and the commission pays gold for his rescue. Fram records another load reading.","f":"During disassembly, a slab falls, seriously injuring {{affectedHeroName}}.","v":{"nf":"The rubble shifts dangerously, but none of the eligible fighters is gravely wounded. The trapped worker must wait for another rescue attempt."}},"E436.2":{"s":"You give supplies to the rescue crew, and the commission pays gold for your help. A voice beneath the rubble asks everyone to stop arguing until he is free."},"E436.3":{"s":"{{heroName}} secures the remaining beams, allowing workers to escape. The commission pays in gold for lives saved.","f":"The remaining support breaks and seriously injures {{affectedHeroName}}.","v":{"nf":"The support collapses, but none of the eligible fighters are gravely wounded. The blockage has to be left until reinforcements."}},"E436.4":{"s":"You leave the construction site until the next experiment. Fram continues to argue that the collapse was purely a matter of calculation."},"E437.1":{"s":"Lem agrees to terminate the contract, and Ezrak pays gold for regained independence. The demon thanks the clerk for the first time without threats.","f":"Other demons declare the termination a violation of hellish regulations and go out to fight."},"E437.2":{"s":"Ezrak pays in gold for a short consultation, and you leave him to carry out his duties with Lem."},"E437.3":{"s":"{{heroName}} finds the mutual agreement clause and formalizes the termination without new obligations. Ezrak gives gold for saved freedom.","f":"The Infernal Archive finds a paid exception for the scribe's errors, and the party is forced to hand over the gold."},"E437.4":{"s":"You leave Ezrak under Lem's authority. The clerk is already ordering the demon to sort the inkwells."},"E438.1":{"s":"You convince Kharos to stop commanding his own rest and just close his eyes. In the morning, the innkeeper thanks with gold for a quiet night.","f":"The demon requires official confirmation of sleep every few minutes. No one can rest."},"E438.2":{"s":"You sell provisions to the innkeeper for another sleepless shift, and he pays gold. From upstairs comes another shout of “I'M RELAXED!”"},"E438.3":{"s":"{{heroName}} conducts a ritual of silence, after which Kharos at least stops screaming. The innkeeper thanks with gold.","f":"The ritual causes a sharp magical response, seriously injuring {{affectedHeroName}}.","v":{"nf":"The ritual is disrupted by a dangerous response, but none of the eligible fighters are gravely wounded. Kharos is still awake."}},"E438.4":{"s":"You choose another tavern. Even on the street you can hear Kharos persistently trying to sleep."},"E439.1":{"s":"You follow the familiar roar with Tik, and his mother comes running, forgetting her anger at once. The fair's traders share supplies.","f":"Armed demons come in response to the noise, mistaking you for the imp’s kidnappers. A skirmish begins."},"E439.2":{"s":"You leave supplies for Tik and show him the way to the fair. The imp tries not to cry sparks onto the dry grass."},"E439.3":{"s":"{{heroName}} quickly finds an angry red demoness at the fair, who recognizes Tik's cry. She thanks in gold for her returned son.","f":"At the fair, {{affectedHeroName}} is attacked by alarmed security and is gravely wounded.","v":{"nf":"Fair security disrupts the search, but none of the available fighters are gravely wounded. The mother has not yet been found."}},"E439.4":{"s":"You leave Tik waiting for the familiar roar beyond the hill. Another sob sets the grass beside him alight."},"E440.1":{"s":"Rax accepts Fluff's choice and withdraws from the monastery. The grateful monks share provisions.","f":"The demon demands the war dog back and calls for armed minions. A skirmish begins."},"E440.2":{"s":"You pay Rax gold, and he leaves Fluff with the monks. They reward the peaceful settlement with supplies.","f":"Rax refuses to consider gold as a replacement for his beast. The dog remains at the monastery, the dispute does not stop."},"E440.3":{"s":"You suggest that Rax visit Fluff without the right to drag him away. The demon agrees and pays gold for the solution.","f":"Rax takes the agreement as a mockery and calls for minions. A skirmish begins."},"E440.4":{"s":"You do not interfere in the choice of a three-eyed dog. Fluff calmly lies down at the monastery gates, and Rax is left with an empty leash."},"E441.1":{"s":"You lead Mart out of the queue with the document cancelling his contract. He rewards you with gold for recovering his soul.","f":"The hellish bailiffs demand a new signature and come out to detain the party. A skirmish begins."},"E441.2":{"s":"You pay the clerical fee, and Fez finally closes Mart's case. The old man thanks with supplies for the time saved."},"E441.3":{"s":"{{heroName}} proves that a canceled contract cannot be restored by a forced signature. Fez returns gold for illegal collection.","f":"The archive discovers an old cancellation fee, and the party loses gold. Mart must still await a final decision."},"E441.4":{"s":"You leave the infernal office before being asked to show the King's signature. Mart carefully holds the paper about the returned soul."},"E442.1":{"s":"You restrain Ord before he can strike and let his reflection explain how it differs from its owner. The double rewards you with gold for saving the mirror.","f":"A real demon calls armed assistants to smash his reflection. A skirmish begins."},"E442.2":{"s":"You carry the mirror out of the room, and the reflection thanks you for your care. Its owner shares supplies as a reward.","f":"The glass turns into a sharp edge and seriously injures {{affectedHeroName}}.","v":{"nf":"The mirror cracks dangerously, but none of the eligible fighters are gravely wounded. The transfer is stopped."}},"E442.3":{"s":"{{heroName}} discovers that the reflection speaks the courteous words Ord himself has forgotten. The demon pays gold for the explanation.","f":"The mirror responds to the inspection with a magical blow, seriously wounding {{affectedHeroName}}.","v":{"nf":"The reflection disrupts the check with a dangerous splash, but none of the eligible fighters are gravely wounded. Its nature remains unclear."}},"E442.4":{"s":"You leave Ord to argue with his more polite self. The reflection apologizes for him even at parting."},"E443.1":{"s":"You hand Pik over to the guards before he can hide behind the angelic watch. Sael rewards you with gold for correcting the error.","f":"Pik calls in accomplices to protect his three years of heavenly protection. A skirmish begins."},"E443.2":{"s":"You buy bread for the road from Tomen. For the first time, Sael carefully reads the name above the bakery."},"E443.3":{"s":"{{heroName}} finds two identical names on the old statement and suggests that Sael submit an official correction. The angel pays in gold.","f":"{{heroName}} does not find a way to change the three-year appointment without a public review. Sael remains confused."},"E443.4":{"s":"You leave Sael to sort out the pickpocket and the real baker. Pik is already asking whether his protection can be renewed."},"E444.1":{"s":"You dry the prayers and find the recipients by name in the surviving lines. Riel thanks you for the recovered bag and gives you supplies.","f":"The ink has spread too much and most of the scrolls have to be put aside. The courier is left with other people's requests."},"E444.2":{"s":"You give Riel provisions for the journey, and she pays you gold for helping complete her deliveries."},"E444.3":{"s":"{{heroName}} compares the contents of prayers with local families and returns the required scroll to everyone. The courier thanks in gold.","f":"{{heroName}} mistakenly combines two similar requests, and the office collects gold for correction."},"E444.4":{"s":"You do not read other people's prayers more than necessary. The girl continues to seriously study the order on the fortress wall."},"E445.1":{"s":"You stand between the riders and the barn, refusing to let them search it. Eliar rewards you with gold for protecting the fugitives.","f":"The pursuers demand to let them through and grab their weapons. A skirmish begins."},"E445.2":{"s":"You give the family supplies and lead the fugitives out through the backyard before the horsemen arrive. Eliar doesn't have to answer their question."},"E445.3":{"s":"{{heroName}} answers questions about the riders' rights, preventing them from asking Eliar about the fugitives. The angel thanks with gold.","f":"The pursuers understand the trick and take up arms. A skirmish begins."},"E445.4":{"s":"You leave Eliar to decide how to tell the truth and not give anyone away. You can already hear hooves on the road."},"E446.1":{"s":"Residents agree to remove the false image of an invincible warrior, and Almer pays in gold for the right not to be a monument to himself.","f":"The angel forbids the dismantling of the consecrated statue, and Almer's request remains unanswered."},"E446.2":{"s":"You pay to alter the monument, replacing its sword with a healer's satchel. The townspeople share supplies in thanks for an honest likeness."},"E446.3":{"s":"The angel recognizes that the will of the living Almer is more important than a convenient legend, and the city pays in gold for the agreed decision.","f":"The Guardian considers the consecration irreversible and does not accept the words of Almer himself. The monument remains the same."},"E446.4":{"s":"You leave healer Almer arguing with his own armoured statue. Toy swords of the saint are already for sale in the square."},"E447.1":{"s":"Nora wins the next game without a single trick, and the bet brings gold to the party. Fael demands one more game.","f":"Fael finally guesses Nora's move, and your bet remains with the manager."},"E447.2":{"s":"You convince Fael to recognize the girl’s skill, and not look for another revenge. Parents thank with supplies.","f":"The angel declares the loss an unsolved riddle and arranges the stones again. He's not ready to stop."},"E447.3":{"s":"{{heroName}} unexpectedly finds a winning combination against Nora, and the spectators pay in gold.","f":"Nora beats {{heroName}} in three moves and takes the bet gold."},"E447.4":{"s":"You leave before Fael organises a tournament bracket for the local children. Nora is already arranging pebbles for her next opponent."},"E448.1":{"s":"You hand the robber over to the guards so that the punishment is decided by the court, not the road. Oriel thanks in gold for the legal decision.","f":"Cass considers the detention a refusal of mercy, and the angels do not allow the prisoner to be taken away. The dispute continues."},"E448.2":{"s":"You support Cass, and the robber quickly gets out of the way without waiting for new theological arguments. Oriel remains unhappy."},"E448.3":{"s":"{{heroName}} offers a trial and the obligation to compensate for harm without reprisals. Both angels recognize this as mercy with responsibility and pay in gold.","f":"{{heroName}} cannot agree on who to entrust control over the robber's promise. The angels continue their argument."},"E448.4":{"s":"You leave the angels debating mercy in the presence of the thief with the most at stake. He has a third suggestion: let him go immediately."},"E449.1":{"s":"You carry the scrolls into fresh air while Xar struggles not to sneeze over the family records. The archivist rewards the rescue with gold.","f":"A sudden fiery sneeze seriously injures {{affectedHeroName}}.","v":{"nf":"A fiery sneeze disrupts the evacuation, but none of the eligible fighters are gravely wounded. The scrolls remain at risk."}},"E449.2":{"s":"You provide portable lamps and provisions to the archivists. Xar pays you gold so they can put out the torches."},"E449.3":{"s":"{{heroName}} cleans out the old chimney, and the air in the cave becomes safer for the scrolls. Rina thanks with gold and supplies.","f":"The old valve breaks off and seriously injures {{affectedHeroName}}.","v":{"nf":"The ventilation collapses dangerously, but none of the eligible fighters are gravely wounded. The work is stopped."}},"E449.4":{"s":"You leave Xar to fight the smoke and his own sneezes. Rina puts out another torch."},"E450.1":{"s":"Saar distracts the chick with a familiar call, and it returns to the sanctuary. The priestess shares supplies for help.","f":"The chick continues to crawl after the King, not reacting to the priestess. The ritual of mentoring remains unresolved."},"E450.2":{"s":"You give Saar supplies to feed the chick, and she thanks you with gold for your care."},"E450.3":{"s":"The King stays as the hatchling's mentor for one brief rite, until it finally heeds the priestess's call. Saar rewards your patience with gold.","f":"The frightened chick accidentally burns the King, seriously injuring him.","v":{"nf":"The chick gets scared and releases fire, but the King is not gravely wounded. The ceremony has to be postponed."}},"E450.4":{"s":"You leave the sanctuary until the priestess decides again. Behind you you can hear the contented rumbling of a chick that has chosen the King."},"E451.1":{"s":"Vesha lights a travel lamp from the ancestral hearth and admits her ancestors guarded the flame, not the walls around it. The settlers reward your help with supplies.","f":"The elders demand that the flame be left in the same stone, and Vesha does not dare to break the custom. Departure is delayed."},"E451.2":{"s":"You give provisions to the settlers, and the elders thank you with gold for their help with the long journey."},"E451.3":{"s":"{{heroName}} performs the rite to preserve the sacred flame in a new brazier, and Vesha accepts the transfer. You receive gold for helping the settlement.","f":"When moving the hearth, the old stone splits and seriously injures {{affectedHeroName}}.","v":{"nf":"The hearth stone is torn from its base, but none of the eligible fighters are gravely wounded. The ceremony is stopped."}},"E451.4":{"s":"You leave Vesha by the three-hundred-year-old fire. The slope above the emptying houses continues to crumble."},"E452.1":{"s":"You open the clogged hot channel and the ice crust begins to melt. The clan supplies the party with supplies for their help.","f":"A jet of hot steam escapes under the ice and seriously injures {{affectedHeroName}}.","v":{"nf":"Steam disrupts the clearing, but none of the eligible fighters are gravely wounded. The bathhouse remains frozen."}},"E452.2":{"s":"You sell fuel and supplies to the clan, and Ro pays gold for the opportunity to heat the bathhouse."},"E452.3":{"s":"{{heroName}} finds a freezing seal beneath the bathhouse and clears the way to the hot spring. The elder rewards you with gold and provisions.","f":"The Ice Seal retaliates, severely wounding {{affectedHeroName}}.","v":{"nf":"The seal repels explorers, but none of the eligible fighters are gravely wounded. The source of the cold has not been identified."}},"E452.4":{"s":"You leave without explaining the purpose of ice to the draconians. Ro still considers the frozen bath a personal insult."},"E453.1":{"s":"You choose the most convincing impossible story, and Iara finally allows the square to laugh. The clan pays in gold for fair judging.","f":"Iara declares that the best liar must first of all know when to stop, and refuses to accept your choice. The tournament continues."},"E453.2":{"s":"Iara declares the third speech a magnificent lie, and your wager wins gold.","f":"Iara doesn't laugh at the compliment and nominates another winner. The bet remains with the stewards."},"E453.3":{"s":"{{heroName}} tells a story that listeners want to believe despite the obvious absurdity. The clan awards gold for the performance.","f":"Iara notices the unfortunate exaggeration, and she has to give up the gold for violating the terms of the competition."},"E453.4":{"s":"You leave the square until Iara decides. The third participant still explains that he did not mean to lie so blatantly."},"E454.1":{"s":"You catch the arsonist carrying fire between the door locks along their runes. Ker rewards his capture with gold.","f":"The caught arsonist calls for armed help from behind the barn. A skirmish begins."},"E454.2":{"s":"You carry sacks of grain through the passage without burning locks and replenish the party's supplies.","f":"The door mechanism bursts into flames during the rescue, severely injuring {{affectedHeroName}}.","v":{"nf":"The flames block the entrance, but none of the eligible fighters are gravely wounded. The grain remains inside."}},"E454.3":{"s":"{{heroName}} notices someone moving from door to door with an incendiary seal, and finds gold on him. Ker thanks for the exposure.","f":"During the chase across the roof, {{affectedHeroName}} is gravely wounded.","v":{"nf":"The pursuit stops at a dangerous area, but none of the eligible fighters are gravely wounded. The arsonist disappears."}},"E454.4":{"s":"You leave the barn until the next flashing door. Ker is still trying to figure out why wet grain doesn't burn."},"E455.1":{"s":"You remind the flock that the moon does not have to appear as an accused and is not responsible for the clouds. Nesha thanks you for the protection and gives you supplies.","f":"Ragar insists that the absence of the moon proves deliberate evasion. The court does not accept the argument."},"E455.2":{"s":"You propose a symbolic fine to the celestial body, and the clan pays in gold for the ridiculous conclusion of the dispute.","f":"Nesha considers such a sentence a humiliation of the sacred moon, and her supporters begin a skirmish."},"E455.3":{"s":"{{heroName}} explains the moon's changing phases without mocking the wolves' right to ask questions. Ragar rewards you with gold for the explanation.","f":"The pack refuses to accept the calendar in lieu of the accused's appearance. The court continues to sit."},"E455.4":{"s":"You leave the court before the moon is sentenced. There is still light above the clearing, which the prosecution considers suspicious."},"E456.1":{"s":"You lift the jammed gate just as Har comes racing towards it. The courier hurtles through the opening and leaves a gift of gold.","f":"The heavy sash breaks off its hinges, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The gate falls dangerously, but none of the eligible fighters are gravely wounded. Haru has to find another way."}},"E456.2":{"s":"You spend supplies clearing the barricade, and Har slips through the open lane. The keeper rewards the help with gold."},"E456.3":{"s":"{{heroName}} releases the broken stopper and opens the gate before impact. The caretaker thanks with gold.","f":"The mechanism reverses, seriously injuring {{affectedHeroName}}.","v":{"nf":"The doors twitch dangerously, but none of the eligible fighters are gravely wounded. The mechanism remains jammed."}},"E456.4":{"s":"You step aside as Har approaches the outpost. The keeper is still shouting that repairs will take ten minutes."},"E457.1":{"s":"Mer easily remembers every detail of Asha's life except her name, and the family realizes that the memory has selectively disappeared. In gratitude they give you supplies.","f":"Mer is afraid of further questions and asks to stop checking. His family has nothing to calm him down yet."},"E457.2":{"s":"You give the family supplies for the journey to the healer, and Asha thanks with gold for the opportunity to find help."},"E457.3":{"s":"{{heroName}} notices a damaged name rune on an old family amulet. Mer recognises it and thanks you with gold.","f":"The name seal responds with a dangerous blow, seriously injuring {{affectedHeroName}}.","v":{"nf":"The amulet refuses the inspection, but none of the eligible fighters is gravely wounded. Mer still cannot recall Asha's name."}},"E457.4":{"s":"You leave Mer alone with his daughter without turning the forgotten name into a public ordeal. Asha takes her father's hand."},"E458.1":{"s":"You acknowledge that Vira warns customers about lies in advance. The guard retreats, and the fox thanks him with gold.","f":"The guard considers the service to be deliberately misleading people and refuses to let Vira go. The dispute continues."},"E458.2":{"s":"You commission a convincing lie from Vira, then expose it before the audience and win gold.","f":"Vira produces a lie so plausible that you cannot disprove it. The fox keeps your payment."},"E458.3":{"s":"{{heroName}} catches Vira concealing the very fact that she is lying. The fox pays gold for being exposed.","f":"Vira proves that she warned about every fiction, and {{heroName}} pays for the lost argument in gold."},"E458.4":{"s":"You walk away without buying a lie with a warranty seal. Vira is already promising her next client a particularly honest deception."},"E459.1":{"s":"The council admits that winning a duel does not mean wanting to rule. Arkhan rewards the party with supplies for defending his freedom to choose.","f":"The elders demand the literal fulfillment of tradition and do not relieve Arkhan from his position."},"E459.2":{"s":"Meira talks about supplies and allies, and the council recognizes her as a suitable clan leader. The family thanks in gold.","f":"Supporters of the force declare the conversation about trade routes an insult to the clan and begin a skirmish."},"E459.3":{"s":"Arkhan willingly chooses to march with you rather than sit on a throne he never wanted. The lion joins your party.","f":"Arkhan refuses to leave until the council decides on a successor. Can't hire him.","v":{"rs":"Arkhan is willing to join the King, but there is no room in the party. He offers gold in thanks for the invitation."}},"E459.4":{"s":"You leave the lion clan the right to appoint its own leader. Meira is still waiting to be asked to speak."},"E460.1":{"s":"You convince Barr to accept his bag and close the theft case. The merchant thanks in gold for the end of the disturbing story.","f":"Barr refuses to accept coins that change the number on their own. Nis continues to ask to free her from the bag."},"E460.2":{"s":"Nis agrees to leave with the party, not wanting to hear any more knocking from the empty room. She becomes a new companion.","f":"Nis can't bring herself to leave without finding out who was knocking behind her back. There is no new fighter.","v":{"rs":"Nis agrees to leave, but there is no room for her in the party. She gives you gold for trying to help."}},"E460.3":{"s":"{{heroName}} finds someone else's counting seal in the bag, changing the readings of the coins. Barr awards gold for finding the cause.","f":"The seal bursts into flames in the researcher's hands, severely injuring {{affectedHeroName}}.","v":{"nf":"The bag responds with a dangerous flash, but none of the eligible fighters are gravely wounded. The origin of the knock remains unknown."}},"E460.4":{"s":"You do not touch gold that the thief herself refused. Barr looks at the bag as if it might knock again."},"E461.1":{"s":"You show B-12 that Elg's order permits the gate to be opened after inspection. The golem allows the caravan through, and Elg pays gold.","f":"B-12 chooses a strict interpretation without a comma and calls armed guards. A skirmish begins."},"E461.2":{"s":"You bypass an imaginary closed passage, wasting supplies on the long journey. The golem continues to demand a comma."},"E461.3":{"s":"{{heroName}} draws up a new order without ambiguity, and B-12 finally lets the carts through. Elg thanks with gold.","f":"The golem discovers a contradiction between the old and new orders and refuses to reconcile them. The passage remains closed."},"E461.4":{"s":"You leave the caravan arguing about a comma. B-12 carefully adds another possible interpretation to its register."},"E462.1":{"s":"You stop K-22, freeing the warehouse from pointless production. Dean thanks you for finally free passage and gives you gold.","f":"K-22 declares the stop a violation of standing orders and raises the security mechanisms. A skirmish begins."},"E462.2":{"s":"You buy metal and supplies from the warehouse while K-22 churns out another unnecessary gear."},"E462.3":{"s":"{{heroName}} finds a lost fragment of the old order that reveals the gear's purpose. Din pays gold for restoring the instruction.","f":"{{heroName}} cannot restore the customer’s name, and the warehouse is charging expenses for archival verification. The treasury is losing gold."},"E462.4":{"s":"You leave K-22 to make parts for an unknown machine. Dean is already looking for a place for a new storage room."},"E463.1":{"s":"You walk through the gate that no longer exists before A-11 can recognise the violation. For the first time, the villagers take the direct path through the old arch.","f":"The guard declares entry without a document illegal and raises armed defense. A skirmish begins."},"E463.2":{"s":"You pass through the village together with the residents, bypassing the old post, spending some provisions on a detour."},"E463.3":{"s":"{{heroName}} disables the outdated order without damaging A-11 and clears the road. The village thanks you with gold.","f":"The protective joints slam shut and seriously injure {{affectedHeroName}}.","v":{"nf":"The guard is dangerously triggered, but none of the available fighters are gravely wounded. The post remains active."}},"E463.4":{"s":"You don't explain to A-11 that the city disappeared sixty years ago. He stops another passerby in an empty opening."},"E464.1":{"s":"You recognise both I-4s as independent beings, and the workshop stops trying to decide which one to destroy. The workers reward you with supplies.","f":"One of the I-4s does not make a decision without proof of his own origin. The dispute continues."},"E464.2":{"s":"One I-4 chooses a new life of service and joins your party. The other wishes him luck finding memories of his own.","f":"Both I-4s prefer to stay together until their history is clarified. It's impossible to hire one.","v":{"rs":"One of the I-4s agrees to join the party, but there is no free space. The workshop thanks in gold for the offer."}},"E464.3":{"s":"{{heroName}} convinces the automata that identical memories do not erase differences in their futures. The workshop pays gold for settling the dispute.","f":"{{heroName}} cannot convince the machines to give up searching for the first instance. They demand that the copier be checked again."},"E464.4":{"s":"You are not proposing a hammer as a solution to an identity dispute. Both I-4s continue to argue about who showed up yesterday."},"E465.1":{"s":"You divide the party into small groups, and the machine counts each group as no more than ten. The bridge allows everyone to pass in turn.","f":"The sensor notices the second shadow of one of the travelers, and supplies have to be wasted while waiting."},"E465.2":{"s":"You pay for a manual pass, and the collector disables double counting for the duration of the transition."},"E465.3":{"s":"{{heroName}} shades the sensor so that it only sees bodies. The collector returns the gold for unnecessary duty.","f":"The machine declares the intervention a violation of the rules and calls armed bridge guards. A skirmish begins."},"E465.4":{"s":"You are wasting supplies on a long crossing. The bridge continues to count the shadows as individual travelers."},"E466.1":{"s":"You explain to S-3 and the others that fear need not prevent a choice; it merely calls for caution. The automata agree to try, and Ren gives you supplies.","f":"The machines consider the probability of breakdown too high and do not turn on. Ren leaves the tools on the table."},"E466.2":{"s":"You give Ren supplies for research, and he pays in gold for the opportunity to teach the machines further."},"E466.3":{"s":"S-3 decides to learn courage on the road and joins your party by choice.","f":"S-3 is not ready to abandon the comrades who have only just learned to fear. He will not join you.","v":{"rs":"S-3 is willing to go, but there is no room for him in the party. Ren rewards your trust with gold."}},"E466.4":{"s":"You leave the machines to decide how to live with the new knowledge of the breakdown. S-3 continues to reflect on courage."},"E467.1":{"s":"You throw five coins into the bucket, and the bear calmly clears the path. The merchants behind breathe a sigh of relief."},"E467.2":{"s":"The bear accepts supplies instead of coins and moves away from the road, allowing the party to pass.","f":"The beast decides that food is no substitute for a shiny board and rushes to defend the bucket. A skirmish begins."},"E467.3":{"s":"{{heroName}} leads the party along the edge of the path while the bear looks at the empty bucket. Nobody pays coins.","f":"The bear turns sharply and seriously injures {{affectedHeroName}}.","v":{"nf":"The bear blocks the passage, but none of the eligible fighters are gravely wounded. We have to look for a way around again."}},"E467.4":{"s":"You spend supplies to bypass the animal post. In the distance, the bear pushes the bucket again towards the next traveler."},"E468.1":{"s":"You reach the bell tower and return the wedding ring to the family, and find gold among the crow's treasures.","f":"On the slippery roof, {{affectedHeroName}} is gravely wounded.","v":{"nf":"The climb fails on a dangerous roof, but none of the eligible fighters are gravely wounded. The raven keeps the ring."}},"E468.2":{"s":"The raven trades the ring for the food you leave and throws in a few coins stolen from others. The family rewards the return of the keepsake with gold.","f":"The bird takes the food, but leaves the ring in the nest. This ends the exchange."},"E468.3":{"s":"{{heroName}} goes up to the nest while the raven is watching the funeral procession, and takes out the ring along with the gold.","f":"A raven attacks at the nest, severely injuring {{affectedHeroName}}.","v":{"nf":"The bird thwarts the attempt to take the ring, but none of the eligible fighters are gravely wounded. The loot remains in the bell tower."}},"E468.4":{"s":"You leave the family to negotiate with the raven on the roof. The priest still holds his hand outstretched, as if the bird is about to return."},"E469.1":{"s":"Following the horse's trail, you find a wounded courier and his purse of gold near the northern path. The owner thanks for the rescue.","f":"On the northern road you are met by armed raiders who detained the courier. A skirmish begins."},"E469.2":{"s":"You give the owner supplies for the search, and he thanks you with gold and saddles a spare horse."},"E469.3":{"s":"{{heroName}} follows the horse's anxious behaviour and finds the missing courier and his travel strongbox. The rescue earns the party gold.","f":"In an ambush by raiders, {{affectedHeroName}} is gravely wounded.","v":{"nf":"The search is met with an armed ambush, but none of the eligible fighters are gravely wounded. The courier has not yet been found."}},"E469.4":{"s":"You leave the search for the courier to the locals and continue on your way. The horse does not allow the bloody saddle to be removed."},"E470.1":{"s":"You reopen the waterway without breaking the entire dam, and the mill wheel turns once more. Tom shares supplies in thanks.","f":"A huge log breaks from the dam and seriously injures {{affectedHeroName}}.","v":{"nf":"The dam shifts dangerously, but none of the eligible fighters are gravely wounded. The mill remains without water."}},"E470.2":{"s":"You buy the remaining supplies from Tom while the otter on the dam keeps a close eye on the people."},"E470.3":{"s":"{{heroName}} is building a diversion so that the mill gets water and the otters save the house. Tom pays in gold and gives away supplies.","f":"During repairs, an embankment collapses, seriously injuring {{affectedHeroName}}.","v":{"nf":"The embankment breaks down, but none of the eligible fighters are gravely wounded. The bypass channel is not ready."}},"E470.4":{"s":"You leave Tom to meet the otter's next construction shift. A new board has already been secured to the top of the dam."},"E471.1":{"s":"You bypass the nearby inn, using extra supplies for a night outdoors. Sure enough, three knocks sound from behind its closed doors."},"E471.2":{"s":"You spend the night on your usual route, hearing no knocks. The innkeeper shares supplies, and the owl never appears.","f":"After the third strike, armed strangers emerge from the hotel. A skirmish begins."},"E471.3":{"s":"You follow a snowy owl to a forgotten hideout and find gold coins there. The bird disappears over the forest.","f":"The owl leads the party too far, and the search for the way back takes up supplies."},"E471.4":{"s":"You keep the letter with you without changing the path. The owl flies after the King for some time, as if awaiting a decision."},"E472.1":{"s":"You drive the boar away from the chest, and the treasure hunters give you the gold from the treasure they found.","f":"The boar protects the dug up chest, and the heated seekers take up arms. A skirmish begins."},"E472.2":{"s":"The boar goes for food and leaves the lid free. Treasure hunters pay in gold for clever bait.","f":"The animal takes the bait and returns straight to the chest. Treasure hunters are left without access to the treasure."},"E472.3":{"s":"{{heroName}} gently lures the boar towards the truffles, giving the treasure hunters time to lift their gold from the chest.","f":"The boar turns around and gravely wounds {{affectedHeroName}}.","v":{"nf":"The beast disrupts the maneuver, but none of the eligible fighters are gravely wounded. The chest remains under it."}},"E472.4":{"s":"You leave the boar on the chest, which he found faster than three seekers. The animal makes itself more comfortable on the lid."},"E473.1":{"s":"Lissa admits that she got the years wrong on the shipping log and pays gold for the corrected log. Horm still holds the invitation to the wedding that took place long ago.","f":"The fairy calls the eighty-year delay a normal seasonal glitch and offers no explanation. The conversation ends."},"E473.2":{"s":"You buy the supplies from the fairy that she carried along with the letters and check if they are suitable for the road."},"E473.3":{"s":"{{heroName}} compares the family names and discovers the invitation was meant for Horm's long-dead namesake. Lissa rewards the discovery with gold.","f":"{{heroName}} does not find the second addressee, and the fairy charges a fee for searching for the old mail. The treasury is losing gold."},"E473.4":{"s":"You congratulate the family on their long-standing wedding and leave. The flowers on the seal are still opening in the sun."},"E474.1":{"s":"You prove that a sleeper cannot be billed without consenting beforehand. Tilla refunds the gold she took unlawfully.","f":"The fairy calls the defenders of her green palace and demands payment even for a dispute. A skirmish begins."},"E474.2":{"s":"You give Tilla the gold and stop arguing about the night in someone else’s dream. She solemnly issues a receipt for the invisible bed."},"E474.3":{"s":"{{heroName}} finds out that no one saw the warning about the fee before going to bed, and demands to cancel the bills. The fairy pays gold.","f":"{{heroName}} cannot prove that the sign did not appear in a dream, and Tilla is charging a fee for the investigation."},"E474.4":{"s":"You leave without promising the fairy to pay for today's sleep. Some people are already afraid of seeing a green fountain at night."},"E475.1":{"s":"You carefully guide your party under a clear stream without disturbing the fish swimming overhead.","f":"Water suddenly falls on the road, washing away some of the supplies. The passage cannot be continued."},"E475.2":{"s":"You pay the fairies for a temporary passage, and Olvi raises the flow above the carts. The caravan moves on."},"E475.3":{"s":"{{heroName}} braces the road beneath the airborne stream, letting the convoy pass safely. The party retains the supplies it found.","f":"The temporary support breaks down, seriously injuring {{affectedHeroName}}.","v":{"nf":"The support cannot withstand the flow, but none of the eligible fighters are gravely wounded. The passage has to be closed."}},"E475.4":{"s":"You spend some of your supplies going around the forest while the fish continue to swim above the road."},"E476.1":{"s":"Mira says that several years have passed in her night forest, although only night has passed at home. Parents thank you with gold for a calm conversation.","f":"The girl is frightened by persistent questions and falls silent. The family asks to stop asking questions."},"E476.2":{"s":"You leave the family supplies for the journey, and the parents decide to wait out the strangeness away from the well."},"E476.3":{"s":"{{heroName}} finds at the well the remains of the magic of displaced time associated with the girl’s return at night. The village thanks you with gold.","f":"The old seal near the well responds with a blow, severely wounding {{affectedHeroName}}.","v":{"nf":"The seal breaks the check, but none of the eligible fighters are gravely wounded. Mira continues to remember what has not yet happened."}},"E476.4":{"s":"You refuse to turn a child's happy return into a public investigation. Mira takes both her parents' hands beside the old well."},"E477.1":{"s":"Bren sings awkwardly but finishes every note, and Essa accepts the fulfilment of his promise. The grateful fairy leaves supplies.","f":"Bren again offers gold instead of a song and cannot bring himself to sing. Essa refuses to close the promise."},"E477.2":{"s":"Essa accepts your payment as a replacement for a promise, and Bren thanks you with supplies for freedom from a forty-year debt.","f":"The fairy does not agree to exchange the song for gold, and Bren remains in debt."},"E477.3":{"s":"{{heroName}} finds a short three-line song that Bren can sing. Essa thanks in gold for what she heard.","f":"Bren gets confused even on a short verse and asks to postpone the performance. The fairy is waiting."},"E477.4":{"s":"You leave Bren and Essa to discuss the song promised forty years ago. The fairy still refuses the gold."},"E478.1":{"s":"You notice how the moving flower-pieces guard the way to the royal flowerbed. Gardener Pelli rewards your observation with supplies.","f":"The flower party changes location before it is possible to catch the pattern. The rules remain unclear."},"E478.2":{"s":"Pelli sells you edible plants for the road without touching the moving checkerboard beds."},"E478.3":{"s":"The King touches the flower piece, revealing a golden cache beneath the soil. The other flowers return to the board.","f":"Sharp magic bursts out of the leaves, seriously injuring the King.","v":{"nf":"The flower figure responds with a dangerous flash, but the King is not gravely wounded. The cache does not open."}},"E478.4":{"s":"You leave the fairy garden and its strange chess game. The figure in the crown looks after the real King for a long time."},"E479.1":{"s":"You lift the carpet off the wooden frame, revealing two goblins inside. Rix refunds the farmers, and your party receives a share of the gold.","f":"Rix calls in armed aides to protect his \"dragon\" business. A skirmish begins."},"E479.2":{"s":"You buy real supplies from goblins instead of carpet dragon services. Smoke continues to flow from the wooden mouth."},"E479.3":{"s":"{{heroName}} brings the frame to the square and shows the hidden legs of two goblins. The peasants pay in gold for exposure.","f":"The wooden frame collapses on {{affectedHeroName}}, causing severe injury.","v":{"nf":"The frame collapses when tested, but no eligible fighters are gravely wounded. Rix manages to hide the device."}},"E479.4":{"s":"You leave Rix's customers to his trade in terrifying illusions. The wooden dragon behind him loudly coughs up stove smoke."},"E480.1":{"s":"You restore Mok's genuine accounts, forcing the robbers to return the cashbox. The cashier pays gold for his protection.","f":"The two security guards declare that taking the cash register is part of their job and go out to confront them."},"E480.2":{"s":"You invest gold at a favorable interest rate and receive a profit on time after the “reorganization” of the bank.","f":"Internal redistribution also includes your contribution, which Zip declares as a voluntary bonus."},"E480.3":{"s":"{{heroName}} finds a forged permit for paying bonuses and makes the robbers return the gold to the cashier. Mok rewards the audit.","f":"Zip presents a paid internal regulation, and the party has to pay gold for the accounting proceedings."},"E480.4":{"s":"You don't put money in a bank where the guards rob their own cash register. The robbers are still standing in masks in front of the authorities."},"E481.1":{"s":"You persuade Pix that extra charges are legitimate only if their rate was agreed in advance. The guests reward you with gold.","f":"The goblin shows the signatures in small print, and the orc refuses to even acknowledge them. The dispute does not end."},"E481.2":{"s":"You pay for rooms and supper and take supplies for the road. The party agrees not to snore until someone produces the measuring horn."},"E481.3":{"s":"{{heroName}} notices that Pix raised his bullhorn to one orc twice, inflating the score. The goblin returns the gold.","f":"Pix produces three witness signatures and demands a fee for false accusation. The treasury is losing gold."},"E481.4":{"s":"You spend the night in the open air, where no one bills you for snoring. The measuring horn rings again in the hotel."},"E482.1":{"s":"You stop the census rockets and send the proper signal to the neighbouring fortress. Wiz rewards you with gold for preventing an alarm.","f":"The fortress guards mistake your attempt to stop the census for a hostile signal. A skirmish begins."},"E482.2":{"s":"You sell supplies to the census takers instead of gunpowder charges, and Wiz pays in gold for their help."},"E482.3":{"s":"{{heroName}} separates flares from census boxes and removes dangerous boxes. The city thanks you with gold.","f":"One of the boxes catches fire during disassembly and seriously injures {{affectedHeroName}}.","v":{"nf":"The charge goes off dangerously, but none of the eligible fighters are gravely wounded. The census still scares the fortress."}},"E482.4":{"s":"You leave the city before the new rocket. The tower is already preparing to announce the arrival of the King with a fire signal."},"E483.1":{"s":"You audit the council and discover that grain vanished from the warehouse under separate seals. The townspeople pay you gold for exposing the discrepancy.","f":"The board refuses to disclose expenses for Mr. Usa's reign. The grain remains without explanation."},"E483.2":{"s":"You sell grain to the town and receive gold. Mr Us personally inspects the first delivery."},"E483.3":{"s":"{{heroName}} holds the meeting next to the rat and finds that Flick was making decisions on her behalf. The council rewards the restored transparency with gold.","f":"Flick declares the meeting not legal enough and charges a fee for the inspection. The treasury is losing gold."},"E483.4":{"s":"You leave Mr Us's apparently stable administration alone. The mayor confidently disappears into the grain warehouse."},"E484.1":{"s":"You buy a ticket to Pruk's future funeral, and the family thanks you with supplies for their support without promising to give a speech."},"E484.2":{"s":"Pruk agrees to give the family part of the proceeds while he can still do it himself. He pays in gold for sound advice.","f":"Pruk argues that pre-funeral income is the untouchable budget of the ceremony. The family gets nothing."},"E484.3":{"s":"Pruk decides to spend the remaining time traveling rather than at his own cash register. He joins the party.","f":"Pruk is not sure that he can withstand the campaign, and remains to prepare the ceremony.","v":{"rs":"Pruk is willing to join the journey, but your party has no room for him. He gives you gold as a token of gratitude."}},"E484.4":{"s":"You do not reserve a place at a funeral without a designated date. Pruk is already discussing advance purchase discounts."},"E485.1":{"s":"You order Tamel and Vors to pull together, and at last the man is safely on solid ground. The grateful survivor rewards you with gold.","f":"The edge of the cliff crumbles under the rescuers, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The edge of the cliff crumbles, but none of the eligible fighters are gravely wounded. Rescue must be continued by other means."}},"E485.2":{"s":"You use supplies to rig a safety rope and pull the man to safety, ignoring the angel and demon's argument. The survivor rewards you with gold."},"E485.3":{"s":"{{heroName}} anchors the rope to solid rock and pulls the man clear before another collapse. Tamel rewards you with gold.","f":"The rope tears free from its anchor, gravely wounding {{affectedHeroName}}.","v":{"nf":"The rope gives dangerously, but none of the eligible fighters is gravely wounded. The rescue remains unfinished."}},"E485.4":{"s":"You call other travellers over with ropes, leaving the argument over credit to its participants. Tamel and Vors are still holding the man above the precipice."},"E486.1":{"s":"Ciel sings an old tune and the door immediately opens without a single turn of the lever. Rokk angrily records the observation.","f":"The elf forgets the last beat, and the extra attempt wastes supplies. The door remains closed."},"E486.2":{"s":"You help Rokk adjust the counterweights, and the lever finally opens the door. The dwarf pays gold for proving the mechanism works.","f":"The gear breaks off and seriously injures {{affectedHeroName}}.","v":{"nf":"The counterbalance disrupts the work, but none of the eligible fighters are gravely wounded. The door doesn't open."}},"E486.3":{"s":"{{heroName}} finds a melody that matches the rhythm of the gears, and the door opens. Rokk thanks with gold and supplies.","f":"The inner lock responds with a sharp blow and gravely wounds {{affectedHeroName}}.","v":{"nf":"The lock operates dangerously, but none of the eligible fighters are gravely wounded. The song hasn't been selected yet."}},"E486.4":{"s":"You go around the workshop along another mine, spending supplies on the transition. Ciel continues to hum in front of the stubborn door."},"E487.1":{"s":"The veterans divide a piece of the standard in half and for the first time can talk about the trophy without arguing. They thank you with supplies.","f":"Both consider the cutting to be the final insult to the memory of the fallen and do not allow the fabric to be touched. There is no peaceful solution."},"E487.2":{"s":"You buy travel supplies from veterans as they continue to reminisce about the same battle from different perspectives."},"E487.3":{"s":"One of the veterans decides that one more hike is better than an endless argument around the fire. He joins the party.","f":"Both consider their service completed and refuse a new campaign.","v":{"rs":"One veteran agrees to serve, but there is no room for another fighter. He gives you gold in farewell."}},"E487.4":{"s":"You leave two people around the same fire to sort out the past. The standard lies between them, but the hands no longer reach for weapons."},"E488.1":{"s":"You open the cemetery gates and find a golden purse near the old guard stone. The crows stop pecking at the bars.","f":"The armed dead, whom the birds held behind the fence, emerge from the cemetery. The battle begins."},"E488.2":{"s":"You leave supplies for Sen to reinforce the fence, and the gravedigger pays gold for your help. The crows keep watch over the gate."},"E488.3":{"s":"{{heroName}} discovers an old seal that causes the crows to keep the undead inside. Sen thanks you for the solution and gives you gold.","f":"The seal responds with a magical blow and seriously injures {{affectedHeroName}}.","v":{"nf":"The seal stops the explorers, but none of the eligible fighters are gravely wounded. The birds continue to guard."}},"E488.4":{"s":"You do not interfere with the work of the crow guard. The skeleton waves a gravestone plaque at them without much success."},"E489.1":{"s":"You switch off M-9 before it can sell Fiz as merchandise again. The goblin rewards you with gold for saving his job.","f":"The side door slams shut during shutdown and seriously injures {{affectedHeroName}}.","v":{"nf":"The mechanism works dangerously, but none of the eligible fighters are gravely wounded. M-9 remains on."}},"E489.2":{"s":"You buy supplies from M-9 and check that Fiz himself was not given away instead of change."},"E489.3":{"s":"{{heroName}} fixes the coin sorter and frees Fiz from the machine's side hatch. The craftsman rewards you with gold and supplies.","f":"The release spring breaks and seriously injures {{affectedHeroName}}.","v":{"nf":"The spring fails the repair, but none of the eligible fighters are gravely wounded. Fiz is still waiting inside."}},"E489.4":{"s":"You move away from M-9 without checking his assessment of the King. Fiz closes the side door, clearly relieved."},"E490.1":{"s":"You persuade Nim to return the stolen name, and the spider answers Saira's call again at last. Its owner rewards you with gold.","f":"Nim calls on her fairy friends to defend her right to play. A skirmish begins."},"E490.2":{"s":"You pay Nim to end the prank, and she restores the spider's name. Saira thanks you with supplies."},"E490.3":{"s":"{{heroName}} teaches Saira to control the spider with gestures until the name is returned. The hostess thanks with gold.","f":"The spider turns sharply and seriously injures {{affectedHeroName}}.","v":{"nf":"The spider refuses to follow the gestures, but none of the eligible fighters are gravely wounded. The fairy still has the name."}},"E490.4":{"s":"You leave Nim keeping a name that is not hers. The spider turns silently towards the sound it can no longer recognise."},"E491.1":{"s":"Bem agrees to pay separately for the dragon's breath, and Koras returns to heat the forge. The smithy pays you gold for settling the dispute.","f":"Bem continues to consider the breath a free instrument and leaves the forge to cool. The contract has not been concluded."},"E491.2":{"s":"You buy supplies from the forge while the craftsmen argue about the price of one breath. Coras pointedly does not look at the forge."},"E491.3":{"s":"{{heroName}} separates the costs of metal, craftsmanship and dragon fire. Both masters accept the reckoning and reward you with gold.","f":"{{heroName}} cannot agree on the cost of breathing, and the forge charges gold for the examination."},"E491.4":{"s":"You do not decide who owns the fire after you exhale. Bem tries to light a cold forge with ordinary coal."},"E492.1":{"s":"May and Horne enter the ring themselves, and the children applaud the rest of the show. The performers share gold from the new takings.","f":"The fastening under the tent breaks, and the troupe has to cancel the act. The children get their money back, but the cash register remains empty."},"E492.2":{"s":"You leave supplies for the artists for the next two days, and they thank you with gold from the last box office. For the first time, May offers to perform without a host."},"E492.3":{"s":"{{heroName}} organises ticket collection at the entrance and keeps the cashbox visible to the whole troupe. The artists reward the honest management with gold.","f":"In the chaos, someone steals part of the proceeds, and the troop's treasury loses gold while trying to make up the shortfall."},"E492.4":{"s":"You leave the circus to decide whether to continue on without its owner. The children are already taking the best places near the tent."},"E493.1":{"s":"You help Erai dig a grave, and the motionless skeletons give way without a fight. The angel thanks with supplies for a worthy burial.","f":"The skeletons do not trust the living, even with shovels, and the funeral is postponed. Nobody raises their weapons."},"E493.2":{"s":"You leave supplies to those who will guard the burial, and Erai thanks you in gold for your help."},"E493.3":{"s":"{{heroName}} conducts a rite honouring both Erai's oath and the skeletons' loyalty. The angel rewards the farewell with gold.","f":"The old body defense responds with a blow and gravely wounds {{affectedHeroName}}.","v":{"nf":"The funeral seal disrupts the ritual, but none of the eligible fighters are gravely wounded. The grave remains empty."}},"E493.4":{"s":"You leave Erai and the skeletons at the body of an old enemy. They stand silently next to each other, still not daring to start the funeral."},"E494.1":{"s":"You give Urak three coins of the required mintage, and Snip finally closes the debt. The goblin thanks you for the accurate calculation and gives you supplies."},"E494.2":{"s":"You convince Snip to accept equal value in other coins, and Urak pays gold for the abandoned six-month chase.","f":"Snip refuses to accept the replacement of the three exact coins. The contract remains outstanding."},"E494.3":{"s":"{{heroName}} finds a provision allowing payment of equal value without violating the requirement of three coins. The demon rewards the solution with gold.","f":"Snip imposes a mandatory fee for a new settlement, and the party loses gold while the dispute continues."},"E494.4":{"s":"You are not interfering with a debt that Urak is willing to repay thirty times over. Snip takes out the old receipt again."},"E495.1":{"s":"Sian accepts a year without hunting and passes on the weapons to the younger ones, and the community thanks the party with supplies for respecting the custom.","f":"The elders demand that the vow be postponed due to winter, and the decision splits the hunting council."},"E495.2":{"s":"You give the community supplies for the time being without the best huntress, and Sian thanks you with gold for your support."},"E495.3":{"s":"{{heroName}} finds the old rule about the transfer of the annual vow with the consent of the community, without violating the sacred sign. The council thanks in gold.","f":"{{heroName}} finds no recognized exception and the council leaves Sian with a difficult choice."},"E495.4":{"s":"You decline to decide what the sacred deer wanted. It lies quietly at Sian's feet while the hunters argue."},"E496.1":{"s":"You clear a safe path past the giant flower without harming its roots. The orcs reward the work with supplies.","f":"The stem suddenly straightens and gravely wounds {{affectedHeroName}}.","v":{"nf":"The roots knock back the tools, but no approaching combatants are gravely wounded. The passage remains closed."}},"E496.2":{"s":"Sol sells you edible parts of the enormous plant, and your wagons gain provisions. The orcs are still preparing their catapult."},"E496.3":{"s":"{{heroName}} makes a path along the edge of the former battlefield without disturbing the flower. The orcs thank you with gold and supplies.","f":"The ground collapses during the detour, gravely wounding {{affectedHeroName}}.","v":{"nf":"The earth gives way beneath the work, but none of the eligible fighters is gravely wounded. The detour must wait."}},"E496.4":{"s":"You leave before the first flower assault in history. Fairy Salt is still trying to explain to the orcs that the plant did not declare war."},"E497.1":{"s":"You find the customer, and he admits that he meant disabling O-6, and not murder. Shira pays in gold to clarify the agreement.","f":"The customer sends armed assistants so as not to discuss the meaning of the order with the contractor. A skirmish begins."},"E497.2":{"s":"O-6 accepts your offer to go with the King while the client decides whether destroying a machine counts as murder. The automaton joins your party.","f":"O-6 refuses to hide and demands a clear ruling under the contract. He will not join the party.","v":{"rs":"O-6 is ready to join, but your party has no room. He offers gold in thanks and stays to await the verdict."}},"E497.3":{"s":"{{heroName}} proves that the contract's legal definition of murder does not apply to destroying an automaton. The guild closes the case and pays gold.","f":"The customer shows a special clause in the contract and charges a fee for its revision. The treasury is losing gold."},"E497.4":{"s":"You leave without settling what ‘murder’ means to Shira and O-6. The automaton continues demanding a definition."},"E498.1":{"s":"You intercept the goose at the dwarf's counter and find the true owner's mark on the purse. The grateful merchant gives out gold.","f":"The goose's pursuers mistake you for a new kidnapper and grab their weapons. A skirmish begins."},"E498.2":{"s":"You purchase travel supplies from several nations while the goose continues its race between stalls."},"E498.3":{"s":"One of the free travellers gladly trades the market for the King's expedition and joins your party.","f":"The travellers prefer to finish the fair before promising their service. No one joins your ranks.","v":{"rs":"A new companion accepts your offer, but there is no room for him. He gives you gold in thanks for the invitation."}},"E498.4":{"s":"You pass through the market of fourteen nations without buying anything. The goose manages to cross the road again with someone else's purse."},"E499.1":{"s":"The living Bert and his ghost agree to share the office until the council can rule on the matter. The grateful townspeople give supplies.","f":"Both Berts insist they alone may sign orders and refuse to acknowledge the other. The council cannot reach a decision."},"E499.2":{"s":"You leave the city council to determine the powers of the two Berts. Both mayors immediately demand to chair the meeting."},"E499.3":{"s":"{{heroName}} compares the times of Bert's death, ghostly return and bodily revival against the city charter. The council rewards the legal reasoning with gold.","f":"{{heroName}} finds a gap in the statute on returning in two states at once, and the office collects a fee. The party loses gold."},"E499.4":{"s":"You leave before a third Bert appears. Behind you, both mayors sign contradictory orders at once."},"E500.1":{"s":"You stay by the fire until dawn and notice an invisible traveller taking up the extra place. Following his footprints, you find a forgotten purse of gold.","f":"When the fifteenth bowl is empty, armed invisible guests emerge from the darkness. The battle begins."},"E500.2":{"s":"You hastily remove the camp, losing some of your provisions on the road. Behind are fourteen empty seats and one that no one has seen."},"E500.3":{"s":"{{heroName}} follows the extra prints and discovers a hidden travel pouch and supplies. The tracks end right next to the party.","f":"The invisible traveler strikes with a sudden blow, seriously injuring {{affectedHeroName}}.","v":{"nf":"An invisible guest disrupts reconnaissance, but none of the eligible fighters are gravely wounded. The extra bowl remains full."}},"E500.4":{"s":"You leave a fifteenth serving by the fire and depart in the morning, never learning for whom it was meant. Another footprint appears in the damp earth."}});
export { OUTCOMES_EN_E431_E500 };
